import test from 'node:test';import assert from 'node:assert/strict';import {isPublicIp,destinationMatches,classifyControl,validateUrl} from './safety.mjs';
test('blocks loopback, private, link-local, metadata, CGNAT and reserved ranges',()=>{for(const ip of ['127.0.0.1','10.0.0.1','169.254.169.254','172.16.2.1','192.168.1.1','100.64.0.1','198.18.0.1','224.0.0.1','::1','::ffff:127.0.0.1','fc00::1','fe80::1','2001:db8::1'])assert.equal(isPublicIp(ip),false,ip);for(const ip of ['8.8.8.8','1.1.1.1','2606:4700:4700::1111'])assert.equal(isPublicIp(ip),true,ip);});
test('literal destination match supports a URL portion and preserves case',()=>{assert.equal(destinationMatches('https://brand.example/offer?a=123','brand.example/offer'),true);assert.equal(destinationMatches('https://brand.example/wrong','brand.example/offer'),false);assert.equal(destinationMatches('https://brand.example/OFFER','/offer'),false);assert.equal(destinationMatches('https://brand.example',''),false);});
test('navigation can proceed while consequential controls are marked for review',()=>{assert.equal(classifyControl({label:'Learn more',href:'https://example.com/learn'}),'navigation');assert.equal(classifyControl({label:'Buy now',href:'https://example.com/order'}),'consequential');assert.equal(classifyControl({label:'Continue',form:true}),'form');assert.equal(classifyControl({label:'Next',disabled:true}),'disabled');assert.equal(classifyControl({label:'Email',href:'mailto:a@example.com'}),'unsupported');});
test('rejects credential URLs and arbitrary network protocols',()=>{for(const s of ['file:///etc/passwd','https://u:p@example.com','http://localhost','https://example.com:8080'])assert.throws(()=>validateUrl(s));assert.equal(validateUrl('https://example.com/path').host,'example.com');});
